def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau(n):
    if n == 1:
        return 1
    factors = prime_factorization(n)
    num_divisors = 1
    for exponent in factors.values():
        num_divisors *= (exponent + 1)
    return num_divisors

# We want to maximize tau(x^2) for x <= 1717
max_tau = 0
best_x = 1

for x in range(1, 1718):
    x_squared = x * x
    current_tau = tau(x_squared)

    if current_tau > max_tau:
        max_tau = current_tau
        best_x = x
